div.script:
(function(){
"use strict";
var g=function(i){return document.getElementById(i)};
var q=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))};
var mk=function(t,a,x){var e=document.createElement(t);if(a)for(var k in a)e.setAttribute(k,a[k]);if(x!=null)e.textContent=x;return e};

var D={theme:"purple",wall:"none",snow:"0",balls:"0",stars:"0",glitch:"0",rain:"0",matrix:"0",grid:"0",blurUnfocus:"1",sessionTimer:"0",tab:"links",gameFilter:"all",favorites:[]};

var W={none:"",anime:"https://images.unsplash.com/photo-1578632767115-351597cf2477?w=1920&q=80",night:"https://images.unsplash.com/photo-1419242902214-272b3f66ee7a?w=1920&q=80",city:"https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=1920&q=80",mountains:"https://images.unsplash.com/photo-1454496522488-7a8e488e8606?w=1920&q=80",space:"https://images.unsplash.com/photo-1462331940025-496dfbfc7564?w=1920&q=80",forest:"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1920&q=80"};
var WL={none:"none",anime:"anime",night:"night",city:"city",mountains:"mountains",space:"space",forest:"forest"};

var MS={},ST={g:function(k){try{return localStorage.getItem(k)}catch(e){return MS[k]||null}},s:function(k,v){try{localStorage.setItem(k,v)}catch(e){MS[k]=v}}};
try{var raw=ST.g("sp10");if(raw){var p=JSON.parse(raw);for(var k in p)if(D.hasOwnProperty(k))D[k]=p[k]}}catch(e){}
function save(){ST.s("sp10",JSON.stringify(D))}

function apply(){
 var b=g("appRoot");
 if(!b)return;
 b.setAttribute("data-t",D.theme);
 b.setAttribute("data-snow",D.snow==="1"?"1":"0");
 b.setAttribute("data-balls",D.balls==="1"?"1":"0");
 b.setAttribute("data-stars",D.stars==="1"?"1":"0");
 b.setAttribute("data-glitch",D.glitch==="1"?"1":"0");
 b.setAttribute("data-rain",D.rain==="1"?"1":"0");
 b.setAttribute("data-matrix",D.matrix==="1"?"1":"0");
 b.setAttribute("data-grid",D.grid==="1"?"1":"0");
 var u=W[D.wall]||"";
 b.style.setProperty("--wall",u?"url('"+u+"')":"none");
 q(".tab").forEach(function(t){t.classList.toggle("active",t.getAttribute("data-tab")===D.tab)});
 ["proxy","browser","links","games","history","settings"].forEach(function(n){
  var pn=g("panel"+n.charAt(0).toUpperCase()+n.slice(1));
  if(pn)pn.classList.toggle("on",D.tab===n);
 });
 q(".setLink,.wallLink").forEach(function(el){
  var kk=el.getAttribute("data-k"),v=el.getAttribute("data-v");
  if(!kk||v==null)return;
  el.classList.toggle("active",String(D[kk])===v);
 });
 q(".chip[data-filter]").forEach(function(c){c.classList.toggle("active",c.getAttribute("data-filter")===D.gameFilter)});
}

setInterval(function(){
 var d=new Date();
 var t=String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0")+":"+String(d.getSeconds()).padStart(2,"0");
 var c=g("clock");if(c)c.textContent=t;
},1000);

(function(){
 var dot=g("curDot"),ring=g("curRing");
 if(!dot||!ring)return;
 if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
 if(window.matchMedia&&window.matchMedia("(hover: none), (pointer: coarse)").matches)return;
 var mx=innerWidth/2,my=innerHeight/2,rx=mx,ry=my;
 function tick(){rx+=(mx-rx)*.18;ry+=(my-ry)*.18;dot.style.transform="translate("+mx+"px,"+my+"px) translate(-50%,-50%)";ring.style.transform="translate("+rx+"px,"+ry+"px) translate(-50%,-50%)";requestAnimationFrame(tick)}
 document.addEventListener("mousemove",function(e){mx=e.clientX;my=e.clientY},{passive:true});
 document.addEventListener("mouseover",function(e){
  var t=e.target,hot=t&&t.closest&&(t.closest("a")||t.closest("button")||t.closest(".ic")||t.closest(".tab")||t.closest(".li")||t.closest(".setLink")||t.closest(".gs")||t.closest(".chip")||t.closest(".gameCard")||t.closest(".siteRow"));
  dot.classList.toggle("hover",!!hot);ring.classList.toggle("hover",!!hot);
 },{passive:true});
 tick();
})();

(function(){
 var cls=[{n:"Algebra II",t:"Mr. Harrison",c:"h1"},{n:"English Literature",t:"Ms. Okafor",c:"h2"},{n:"AP World History",t:"Mr. Delgado",c:"h3"},{n:"Chemistry",t:"Mrs. Patel",c:"h4"},{n:"Physical Education",t:"Coach Reynolds",c:"h2"},{n:"Computer Science",t:"Ms. Chen",c:"h1"}];
 var wrap=g("fakeClasses");
 if(!wrap)return;
 cls.forEach(function(c){
  var card=mk("div",{class:"classCard"});
  var hdr=mk("div",{class:"hdr "+c.c});hdr.appendChild(document.createTextNode(c.n));
  hdr.appendChild(mk("div",{class:"teacher"},c.t));card.appendChild(hdr);
  card.appendChild(mk("div",{class:"body"},"2 assignments due · no announcements"));
  wrap.appendChild(card);
 });
})();

var toast=g("toast");
function say(m){if(!toast)return;toast.textContent=m;toast.classList.add("show");clearTimeout(say.t);say.t=setTimeout(function(){toast.classList.remove("show")},1500)}
function copy(t,b){
 var ok=function(){if(b){var o=b.textContent;b.textContent="✓";clearTimeout(copy.t);copy.t=setTimeout(function(){b.textContent=o},900)}say("copied")};
 try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(ok,function(){fb()})}else{fb()}}catch(e){fb()}
 function fb(){try{var ta=document.createElement("textarea");ta.value=t;ta.style.position="fixed";ta.style.opacity="0";document.body.appendChild(ta);ta.select();document.execCommand("copy");document.body.removeChild(ta);ok()}catch(e){ok()}}
}

var popupWarned=false;
function cloakOpen(url,label){
 var w=null;
 try{w=window.open("about:blank","_blank")}catch(e){}
 if(!w){
  if(!popupWarned){popupWarned=true;say("popups blocked — allow once")}
  try{window.location.href=url}catch(e){}
  return null;
 }
 try{
  var d=w.document;
  d.open();
  d.write("<!DOCTYPE html><html><head><title>"+(label||"Page")+"</title><style>html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#000}iframe{position:fixed;inset:0;width:100%;height:100%;border:0}</style></head><body><iframe src=\""+url.replace(/"/g,"%22")+"\" referrerpolicy=\"no-referrer\"></iframe></body></html>");
  d.close();
 }catch(e){try{w.location.href=url}catch(e2){}}
 logHist(url,"cloak");
 return w;
}
function testBlank(){
 var w=window.open("about:blank","_blank");
 if(!w){say("popup blocked");return}
 try{w.document.body.innerHTML="<div style='font:16px monospace;padding:30px;color:#0a0'>about:blank write works.<br>address bar shows about:blank.<br><br>close this tab.</div>";w.document.body.style.background="#000";say("test opened")}catch(e){say("write blocked")}
}

var pOn=false;
function panic(){pOn=!pOn;var fp=g("fakePage");if(fp)fp.classList.toggle("on",pOn);document.title=pOn?"Classes":"Study Portal"}
document.addEventListener("keydown",function(e){if(e.key==="Escape")panic()});
addEventListener("blur",function(){if(D.blurUnfocus==="1"&&g("appRoot"))g("appRoot").classList.add("hidden")});
addEventListener("focus",function(){if(g("appRoot"))g("appRoot").classList.remove("hidden")});

var HIST=[];
function logHist(url,method){
 HIST.unshift({t:Date.now(),u:url,m:method});
 if(HIST.length>200)HIST.length=200;
 renderHist();
}
function renderHist(){
 var list=g("histList"),empty=g("histEmpty");
 if(!list)return;
 list.innerHTML="";
 if(!HIST.length){empty.style.display="block";return}
 empty.style.display="none";
 HIST.slice(0,100).forEach(function(h){
  var row=mk("div",{class:"histItem"});
  var tm=new Date(h.t);
  row.appendChild(mk("span",{class:"t"},String(tm.getHours()).padStart(2,"0")+":"+String(tm.getMinutes()).padStart(2,"0")));
  row.appendChild(mk("span",{class:"u"},h.u));
  row.appendChild(mk("span",{class:"m"},h.m));
  var opens=mk("button",{class:"btn"},"open");
  opens.addEventListener("click",function(e){e.stopPropagation();cloakOpen(h.u)});
  row.appendChild(opens);
  list.appendChild(row);
 });
}
var hc=g("histClear");if(hc)hc.addEventListener("click",function(){HIST.length=0;renderHist();say("cleared")});

var PROXIES=[
 {n:"proxy-1",b:"https://www.croxyproxy.com/",t:"path",lane:"freedns"},
 {n:"proxy-2",b:"https://www.blockaway.net/",t:"path",lane:"freedns"},
 {n:"proxy-3",b:"https://www.croxyproxy.rocks/",t:"path",lane:"freedns"},
 {n:"proxy-4",b:"https://www.croxyproxy.net/",t:"path",lane:"freedns"},
 {n:"proxy-5",b:"https://www.croxyproxy.com/_en/",t:"path",lane:"freedns"},
 {n:"proxy-6",b:"https://www.blockaway.net/",t:"path",lane:"freedns"},
 {n:"translate",b:"https://translate.google.com/translate?sl=auto&tl=en&u=",t:"prefix",lane:"freedns"}
];

var proxySelect=g("proxySelect");
function renderProxies(){
 if(!proxySelect)return;
 proxySelect.innerHTML="";
 PROXIES.forEach(function(p,i){
  var opt=mk("option",{value:String(i)},p.n);
  proxySelect.appendChild(opt);
 });
 proxySelect.value="0";
 updateProxyMeta();
}
function updateProxyMeta(){
 var i=parseInt(proxySelect.value,10)||0;
 var p=PROXIES[i];
 if(!p)return;
 if(g("proxyName"))g("proxyName").textContent=p.n;
 if(g("proxyLane")){g("proxyLane").textContent=p.lane;g("proxyLane").className="lane "+p.lane}
}
if(proxySelect)proxySelect.addEventListener("change",updateProxyMeta);

function normalize(t){
 t=(t||"").trim();
 if(!t)return "";
 if(/^https?:\/\//i.test(t))return t;
 if(/^[\w-]+(\.[\w-]+)+(\/.*)?$/.test(t))return "https://"+t;
 return "https://www.google.com/search?q="+encodeURIComponent(t);
}
function proxyGo(cloak){
 var i=parseInt(proxySelect.value,10)||0;
 var p=PROXIES[i];
 var target=normalize(g("proxyInput").value);
 if(!target){say("enter a url");return}
 var via=p.t==="prefix"?p.b+encodeURIComponent(target):p.b+target;
 if(cloak){cloakOpen(via,"Proxy");return}
 g("proxyState").textContent="loading...";
 g("proxyFrame").classList.remove("hide");
 g("proxyFallback").classList.remove("on");
 g("proxyFrame").src=via;
 logHist(target,"proxy:"+p.n);
 setTimeout(function(){
  try{
   var d=g("proxyFrame").contentDocument;
   if(!d||d.location.href==="about:blank"||!d.body||d.body.childNodes.length===0){
    g("proxyFrame").classList.add("hide");
    g("proxyFallback").classList.add("on");
    g("proxyState").textContent="blocked — try CLOAK";
   } else {
    g("proxyState").textContent="loaded";
   }
  }catch(e){g("proxyState").textContent="loaded"}
 },4000);
}
var pg=g("proxyGo");if(pg)pg.addEventListener("click",function(){proxyGo(false)});
var pc=g("proxyCloak");if(pc)pc.addEventListener("click",function(){proxyGo(true)});
var pi=g("proxyInput");if(pi)pi.addEventListener("keydown",function(e){if(e.key==="Enter")proxyGo(false)});
renderProxies();

function browserGo(){
 var t=normalize(g("browserInput").value);
 if(!t){say("type a url");return}
 g("browserState").textContent="opened: "+t.slice(0,40);
 cloakOpen(t,"Browse");
}
var bg=g("browserGo");if(bg)bg.addEventListener("click",browserGo);
var bc=g("browserCloak");if(bc)bc.addEventListener("click",browserGo);
var bi=g("browserInput");if(bi)bi.addEventListener("keydown",function(e){if(e.key==="Enter")browserGo()});

