function lane(u){
 u=String(u).toLowerCase();
 if(u.indexOf("s3.amazonaws.com")>-1||u.indexOf("s3.us-east")>-1||u.indexOf("s3.dualstack")>-1||u.indexOf(".s3.")>-1)return "s3";
 if(u.indexOf("jsdelivr.net")>-1)return "jdel";
 return "freedns";
}

var groupsEl=g("groups");
function renderLinks(){
 if(!groupsEl)return;
 var frag=document.createDocumentFragment();
 DATA.forEach(function(gr){
  var d=mk("div",{class:"group open"});
  var s=mk("button",{class:"gs",type:"button"});
  var gh=mk("div",{class:"gh"});
  gh.appendChild(mk("span",{class:"kao"},gr.e));
  gh.appendChild(mk("span",{class:"gn"},gr.n));
  gh.appendChild(mk("span",{class:"pill"},String(gr.l.length)));
  gh.appendChild(mk("span",{class:"chev"},"▾"));
  s.appendChild(gh);d.appendChild(s);
  var b=mk("div",{class:"gb"});
  gr.l.forEach(function(u){
   var li=mk("div",{class:"li"});
   var sp=mk("span",{class:"u"});
   var stripped=u.replace(/^https?:\/\//,"");
   var h=stripped.split("/")[0];
   sp.innerHTML="https://<b></b>";
   var bEl=sp.querySelector("b");if(bEl)bEl.textContent=h;
   sp.appendChild(document.createTextNode(stripped.slice(h.length)));
   li.appendChild(sp);
   var acts=mk("div",{class:"acts"});
   var cb=mk("button",{type:"button",class:"btn"},"copy");
   cb.addEventListener("click",function(e){e.stopPropagation();copy(u,cb)});
   acts.appendChild(cb);
   li.appendChild(acts);
   li.addEventListener("click",function(){cloakOpen(u,"Link")});
   li.addEventListener("contextmenu",function(e){e.preventDefault();window.open(u,"_blank","noopener")});
   b.appendChild(li);
  });
  d.appendChild(b);frag.appendChild(d);
 });
 groupsEl.appendChild(frag);
}

var search=g("search"),empty=g("empty");
function updateSearch(){
 var term=(search.value||"").trim().toLowerCase();
 if(/^[0-9+\-*/(). ]+$/.test(term)&&/[0-9]/.test(term)){
  try{var rr=Function("return ("+term+")")();if(typeof rr==="number"&&isFinite(rr))say("= "+rr)}catch(e){}
 }
 var gc=0,lc=0;
 var all=groupsEl.querySelectorAll(".group");
 for(var i=0;i<all.length;i++){
  var grp=all[i];
  var gn=grp.querySelector(".gn");
  var hitName=!term||(gn&&gn.textContent.toLowerCase().indexOf(term)>-1);
  var its=grp.querySelectorAll(".li"),n=0;
  for(var j=0;j<its.length;j++){
   var it=its[j],ue=it.querySelector(".u");
   var hit=hitName||(ue&&ue.textContent.toLowerCase().indexOf(term)>-1);
   it.classList.toggle("hidden",!hit);if(hit)n++;
  }
  var pill=grp.querySelector(".pill");if(pill)pill.textContent=n;
  grp.classList.toggle("hidden",!n);
  if(term&&n)grp.classList.add("open");
  if(n){gc++;lc+=n}
 }
 empty.classList.toggle("show",!gc);
}

var gameGrid=g("gameGrid");
function renderGames(){
 if(!gameGrid)return;
 var frag=document.createDocumentFragment();
 GAMES.forEach(function(gm){
  var ln=lane(gm.u);
  var card=mk("div",{class:"gameCard"});card.setAttribute("data-lane",ln);
  var cov=mk("div",{class:"cover"});cov.style.backgroundImage="url('"+gm.c+"')";card.appendChild(cov);
  var info=mk("div",{class:"info"});
  var nm=mk("div",{class:"name"});
  nm.appendChild(document.createTextNode(gm.n));
  nm.appendChild(mk("span",{class:"badge "+(ln==="jdel"?"jdel":ln)},ln==="jdel"?"jsdelivr":ln));
  info.appendChild(nm);
  info.appendChild(mk("div",{class:"desc"},gm.d));
  card.appendChild(info);
  card.addEventListener("click",function(){cloakOpen(gm.u,"Game")});
  card.addEventListener("contextmenu",function(e){e.preventDefault();window.open(gm.u,"_blank","noopener")});
  frag.appendChild(card);
 });
 gameGrid.appendChild(frag);
}
function applyGameFilter(){
 q(".gameCard").forEach(function(c){c.classList.toggle("hidden",D.gameFilter!=="all"&&c.getAttribute("data-lane")!==D.gameFilter)});
}

var sitesGrid=g("sitesGrid");
function renderSites(){
 if(!sitesGrid)return;
 var seen={},frag=document.createDocumentFragment();
 DATA.forEach(function(gr){
  gr.l.forEach(function(u){
   if(seen[u])return;seen[u]=1;
   var row=mk("div",{class:"siteRow"});
   row.appendChild(mk("span",{class:"k"},gr.e+" "+gr.n));
   var sp=mk("span",{class:"u"});sp.textContent=u;row.appendChild(sp);
   var acts=mk("div",{class:"acts"});
   var cb=mk("button",{class:"btn"},"copy");
   cb.addEventListener("click",function(e){e.stopPropagation();copy(u,cb)});
   acts.appendChild(cb);row.appendChild(acts);
   row.addEventListener("click",function(){cloakOpen(u,"Site")});
   row.addEventListener("contextmenu",function(e){e.preventDefault();window.open(u,"_blank","noopener")});
   frag.appendChild(row);
  });
 });
 sitesGrid.appendChild(frag);
}

var wallGrid=g("wallGrid");
function renderWalls(){
 if(!wallGrid)return;
 var frag=document.createDocumentFragment();
 Object.keys(W).forEach(function(k){
  var w=mk("div",{class:"wallLink","data-k":"wall","data-v":k});
  if(k==="none")w.setAttribute("data-w","none");
  else w.style.backgroundImage="url('"+W[k]+"')";
  w.appendChild(mk("span",null,WL[k]||k));
  frag.appendChild(w);
 });
 wallGrid.appendChild(frag);
}

var pal=g("palette"),palIn=g("paletteInput"),palList=g("paletteList");
function palItems(){
 var L=[
  {t:"tab: proxy",k:"tab",fn:function(){D.tab="proxy";save();apply()}},
  {t:"tab: browser",k:"tab",fn:function(){D.tab="browser";save();apply()}},
  {t:"tab: links",k:"tab",fn:function(){D.tab="links";save();apply()}},
  {t:"tab: games",k:"tab",fn:function(){D.tab="games";save();apply()}},
  {t:"tab: history",k:"tab",fn:function(){D.tab="history";save();apply()}},
  {t:"tab: settings",k:"tab",fn:function(){D.tab="settings";save();apply()}},
  {t:"panic toggle",k:"esc",fn:panic},
  {t:"test about:blank",k:"test",fn:testBlank},
  {t:"clear history",k:"hist",fn:function(){HIST.length=0;renderHist();say("cleared")}},
  {t:"toggle snow",k:"snow",fn:function(){D.snow=D.snow==="1"?"0":"1";save();apply()}},
  {t:"toggle rain",k:"rain",fn:function(){D.rain=D.rain==="1"?"0":"1";save();apply()}},
  {t:"toggle matrix",k:"matrix",fn:function(){D.matrix=D.matrix==="1"?"0":"1";save();apply()}},
  {t:"bookmarklet panel",k:"bml",fn:function(){if(g("bmlPanel"))g("bmlPanel").classList.toggle("on")}},
  {t:"export config",k:"export",fn:function(){copy(JSON.stringify(D,null,2))}}
 ];
 DATA.forEach(function(gr){gr.l.forEach(function(u){L.push({t:"open: "+u.replace(/^https?:\/\//,"").slice(0,50),k:u,fn:function(){cloakOpen(u,"Palette")}})})});
 return L;
}
var palCache=null;
function openPal(){if(!palCache)palCache=palItems();pal.classList.add("on");palIn.value="";renderPal("");palIn.focus()}
function closePal(){pal.classList.remove("on")}
function renderPal(term){
 if(!palCache)palCache=palItems();
 term=(term||"").toLowerCase();
 var items=palCache.filter(function(i){return !term||i.t.toLowerCase().indexOf(term)>-1||i.k.toLowerCase().indexOf(term)>-1}).slice(0,30);
 palList.innerHTML="";
 items.forEach(function(i,idx){
  var el=mk("div",{class:"paletteItem"+(idx===0?" sel":"")});
  el.appendChild(mk("span",{class:"kk"},i.k));
  el.appendChild(mk("span",{class:"ttl"},i.t));
  el.addEventListener("click",function(){i.fn();closePal()});
  palList.appendChild(el);
 });
}
if(palIn){
 palIn.addEventListener("input",function(){renderPal(palIn.value)});
 palIn.addEventListener("keydown",function(e){
  if(e.key==="Escape")closePal();
  else if(e.key==="Enter"){var s=palList.querySelector(".sel");if(s)s.click()}
 });
}
if(pal)pal.addEventListener("click",function(e){if(e.target===pal)closePal()});

var bb=g("btnBml");if(bb)bb.addEventListener("click",function(){if(g("bmlPanel"))g("bmlPanel").classList.toggle("on")});
var bc2=g("bmlClose");if(bc2)bc2.addEventListener("click",function(){if(g("bmlPanel"))g("bmlPanel").classList.remove("on")});
var br=g("bmlRun");if(br)br.addEventListener("click",function(){
 var c=g("bmlText").value.trim();if(!c)return;
 if(c.indexOf("javascript:")===0)c=c.slice(11);
 try{Function(c)();say("ran")}catch(e){say("error: "+e.message)}
});
var bs=g("bmlSave");if(bs)bs.addEventListener("click",function(){ST.s("sp10-bml",g("bmlText").value);say("saved")});
var bl=g("bmlLoad");if(bl)bl.addEventListener("click",function(){var v=ST.g("sp10-bml")||"";g("bmlText").value=v;say(v?"loaded":"empty")});
var bcl=g("bmlClear");if(bcl)bcl.addEventListener("click",function(){g("bmlText").value=""});

var bp=g("btnPalette");if(bp)bp.addEventListener("click",openPal);
var bpn=g("btnPanic");if(bpn)bpn.addEventListener("click",panic);
var ck=g("ckTest");if(ck)ck.addEventListener("click",testBlank);

var ce=g("cfgExport");if(ce)ce.addEventListener("click",function(){copy(JSON.stringify(D,null,2));say("exported")});
var ci=g("cfgImport");if(ci)ci.addEventListener("click",function(){
 var inp=prompt("paste config:");if(!inp)return;
 try{var p=JSON.parse(inp);for(var k in p)if(D.hasOwnProperty(k))D[k]=p[k];save();apply()}catch(e){say("invalid")}
});
var cr=g("cfgReset");if(cr)cr.addEventListener("click",function(){
 D={theme:"purple",wall:"none",snow:"0",balls:"0",stars:"0",glitch:"0",rain:"0",matrix:"0",grid:"0",blurUnfocus:"1",sessionTimer:"0",tab:"links",gameFilter:"all",favorites:[]};
 save();apply();applyGameFilter();say("reset")
});

document.addEventListener("click",function(ev){
 var t=ev.target;if(!t||!t.closest)return;
 var tab=t.closest(".tab");
 if(tab&&tab.getAttribute("data-tab")){
  ev.preventDefault();
  D.tab=tab.getAttribute("data-tab");save();apply();return;
 }
 var chip=t.closest(".chip[data-filter]");
 if(chip){ev.preventDefault();D.gameFilter=chip.getAttribute("data-filter");save();apply();applyGameFilter();return}
 var sl=t.closest(".setLink,.wallLink");
 if(sl&&sl.getAttribute("data-k")){
  ev.preventDefault();
  var kk=sl.getAttribute("data-k"),v=sl.getAttribute("data-v");
  if(D.hasOwnProperty(kk)){D[kk]=v;save();apply()}
  return;
 }
 var gs=t.closest(".gs");
 if(gs){ev.preventDefault();var grp=gs.closest(".group");if(grp)grp.classList.toggle("open");return}
},true);

function buildSnow(){var s=g("snowFx");if(!s)return;s.innerHTML="";var f=document.createDocumentFragment();for(var i=0;i<60;i++){var p=mk("i");var l=Math.random()*100,d=6+Math.random()*10,dl=-Math.random()*d,dx=(Math.random()*40-20).toFixed(1),sz=(3+Math.random()*4).toFixed(1);p.setAttribute("style","left:"+l+"%;width:"+sz+"px;height:"+sz+"px;--dx:"+dx+"px;animation-duration:"+d+"s;animation-delay:"+dl+"s;");f.appendChild(p)}s.appendChild(f)}
function buildBalls(){var b=g("ballFx");if(!b)return;b.innerHTML="";var f=document.createDocumentFragment();for(var i=0;i<24;i++){var p=mk("i");var l=Math.random()*100,d=8+Math.random()*14,dl=-Math.random()*d,bx=Math.round(Math.random()*180-90);p.setAttribute("style","left:"+l+"%;--bx:"+bx+"px;animation-duration:"+d+"s;animation-delay:"+dl+"s;");f.appendChild(p)}b.appendChild(f)}
function buildStars(){var s=g("starsFx");if(!s)return;s.innerHTML="";var f=document.createDocumentFragment();for(var i=0;i<20;i++){var p=mk("i");var l=Math.random()*100,dl=Math.random()*6;p.setAttribute("style","left:"+l+"%;animation-delay:"+dl+"s;");f.appendChild(p)}s.appendChild(f)}
function buildRain(){var r=g("rainFx");if(!r)return;r.innerHTML="";var f=document.createDocumentFragment();for(var i=0;i<80;i++){var p=mk("i");var l=Math.random()*100,d=0.6+Math.random()*1.2,dl=-Math.random()*d,op=(0.2+Math.random()*0.5).toFixed(2);p.setAttribute("style","left:"+l+"%;animation-duration:"+d+"s;animation-delay:"+dl+"s;opacity:"+op);f.appendChild(p)}r.appendChild(f)}
function buildMatrix(){var m=g("matrixFx");if(!m)return;var cols=Math.max(20,Math.floor(innerWidth/16)),lines=Math.max(30,Math.floor(innerHeight/16)),ch="01アイウエオカキクケコサシスセソabcdefghijklmnopqrstuvwxyz#$%&*",out=[];for(var y=0;y<lines;y++){var row="";for(var x=0;x<cols;x++)row+=ch[Math.floor(Math.random()*ch.length)];out.push(row)}m.textContent=out.join("\n")}
if("requestIdleCallback" in window)requestIdleCallback(function(){buildSnow();buildBalls();buildStars();buildRain()});
else setTimeout(function(){buildSnow();buildBalls();buildStars();buildRain()},0);
var mB=false;function ensureM(){if(mB)return;mB=true;buildMatrix();setInterval(buildMatrix,5000)}
var oA=apply;apply=function(){oA();if(D.matrix==="1")ensureM()};

document.addEventListener("keydown",function(e){
 if(e.key==="k"&&(e.ctrlKey||e.metaKey)){e.preventDefault();openPal();return}
 if(e.key==="/"&&document.activeElement!==search&&document.activeElement!==palIn&&g("browserInput")&&document.activeElement!==g("browserInput")&&g("proxyInput")&&document.activeElement!==g("proxyInput")){e.preventDefault();search.focus();search.select()}
});
if(search)search.addEventListener("input",updateSearch);

var sStart=Date.now(),warned=false;
setInterval(function(){
 var m=parseInt(D.sessionTimer,10)||0;if(m===0)return;
 var el=(Date.now()-sStart)/60000;
 if(el>=m&&!warned){warned=true;var w=g("sessionWarn");if(w){w.textContent="session "+Math.round(el)+" min";w.classList.add("on");setTimeout(function(){w.classList.remove("on")},6000)}}
},30000);

renderLinks();
renderWalls();
renderGames();
renderSites();
renderHist();
apply();
applyGameFilter();
updateSearch();
})();
